//! 🧪️ Every original metadata field matches the independent portable Pack suffix without wire shadows.
use crate::{ToolRunId,ToolRunIdentity,ToolRunTick,ToolRunTickWriter,ToolRunTickWireCursor,ToolRunPayloadUpdate};
use semio_framework_value::retained_clone::RetainedCloneGrant;
fn hex(text:&str)->Vec<u8>{text.as_bytes().chunks_exact(2).map(|pair|u8::from_str_radix(std::str::from_utf8(pair).unwrap(),16).unwrap()).collect()}
#[test]
fn original_payload_stream_wire_metadata_matches_buffer_fixture_and_original_custody(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let identity=ToolRunIdentity{id:ToolRunId{app_instance_id:7,run:17},generation:3,base_revision:[0x11;32]};let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:131072,maximum_release_bytes:131072,maximum_depth:64};
 for row in law["cases"].as_array().unwrap(){let update:ToolRunPayloadUpdate=serde_json::from_value(row["update"].clone()).unwrap();let mut writer=ToolRunTickWriter::new(identity);writer.payload(vec![23;row["length"].as_u64().unwrap()as usize]);writer.payload_update=Some(update);let original=writer.payload.as_ref().unwrap().as_ptr();let expected=writer.clone().finish().unwrap().encode().unwrap();assert!(expected.ends_with(&hex(row["suffix"].as_str().unwrap())));assert_eq!(ToolRunTick::decode(&expected).unwrap().payload_update,Some(update));let(mut wire,receipt)=ToolRunTickWireCursor::admit(&writer,None,g).unwrap().unwrap();assert!(receipt.fits(g));let mut output=Vec::new();for _ in 0..100000{if wire.is_complete(){break;}if !wire.chunk().is_empty(){output.extend_from_slice(wire.chunk());let p=wire.acknowledge_chunk(g);assert!(p.fits(g));continue;}let d=wire.advance_demands(&writer,None).unwrap();let denied=RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes.saturating_sub(1),..g};let(p,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||wire.advance(&writer,None,denied).unwrap());assert_eq!(p,Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let(p,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||wire.advance(&writer,None,g).unwrap());assert!(p.fits(g));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(writer.payload.as_ref().unwrap().as_ptr(),original);}assert!(wire.is_complete());assert_eq!(output,expected);assert!(wire.close_step(g).fits(g));assert!(wire.terminal_is_empty());let mut missing=writer.clone().finish().unwrap();missing.payload_update=None;assert!(missing.encode().is_err());missing.payload_update=Some(update);missing.payload=None;assert!(missing.encode().is_err());}
}
